import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Reservations","description":"","frontmatter":{},"headers":[],"relativePath":"user/center/reservations.md","filePath":"user/center/reservations.md"}'),s={name:"user/center/reservations.md"};function i(r,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="reservations" tabindex="-1">Reservations <a class="header-anchor" href="#reservations" aria-label="Permalink to &quot;Reservations&quot;">​</a></h1><p><strong>Reservations</strong> lists every booking at your center. Filter by date, status or service, or use the <strong>calendar</strong>.</p><p>Every booking has a 6-character <strong>code</strong> (for example <code>K7QX2M</code>). A client can show it at the desk and you can look the booking up by it.</p><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>Booked, waiting for payment</td></tr><tr><td><strong>Confirmed</strong></td><td>Paid (or cash on arrival)</td></tr><tr><td><strong>Completed</strong></td><td>The visit happened</td></tr><tr><td><strong>No-show</strong></td><td>The client did not come</td></tr><tr><td><strong>Cancelled</strong></td><td>Cancelled; the slot is free again</td></tr></tbody></table><p>Pending, confirmed, completed and no-show bookings all <strong>use up capacity</strong>. Only cancelled ones free it.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p>You need the reservations permission.</p><ul><li><strong>Create</strong> a booking for a client. Use <strong>quote</strong> first to check the price and availability.</li><li><strong>Find a client by phone</strong> at the desk. You can find any client of the app, even one who has never booked with you. If nobody has that phone, <strong>add the client</strong> with their phone, first name and last name. They join your client list and can later sign in to the app with the same phone.</li><li><strong>Pick the horse</strong> a booking is for, from your center&#39;s horses (yours or your clients&#39;), or remove it. You need the edit permission. This works whatever the booking&#39;s status.</li><li><strong>Cancel</strong> a booking.</li><li><strong>Complete</strong> or mark <strong>no-show</strong>, but only after the slot has started.</li><li><strong>Reschedule</strong> a pending or confirmed booking to another slot. The price must stay the same; if it would change, cancel and rebook. If the new slot is full you are told there are not enough places; confirm the move to book it anyway (this overbooks the slot). Other rules, such as opening hours, still apply.</li></ul><h2 id="stabling-a-horse" tabindex="-1">Stabling a horse <a class="header-anchor" href="#stabling-a-horse" aria-label="Permalink to &quot;Stabling a horse&quot;">​</a></h2><p>To board a client&#39;s horse, book a <strong>stabling</strong> stay from the horse. Choose the stabling service, a <strong>monthly price</strong> or the <strong>price per day</strong>, the start date, and any extras.</p><ul><li>A monthly price covers its months from the start date (one month from 1 December ends on 31 December).</li><li>The price per day starts a stay with no end date. It lasts until you end or cancel it, and the first day is charged.</li><li>Only horses that belong to a client can be stabled. The client is the horse&#39;s owner.</li><li>A horse can only have one stay at a time. Complete or cancel the current stay before booking an overlapping one.</li><li>You can enter a <strong>different total</strong>. It is charged as you enter it, and offers and coupons are not applied.</li><li>Mark the stay <strong>paid</strong> if the client already paid. Otherwise it is confirmed with the payment still to collect.</li><li><strong>End a stay</strong> when the horse leaves. Pick the last day (today by default; it can&#39;t be after a monthly stay&#39;s planned end). The stay is completed and the horse is free for a new stay. The price is not changed, so settle any difference with the client yourself.</li><li>A stabling stay cannot be rescheduled. Cancel it and book again.</li></ul><h2 id="cancelling-and-refunds" tabindex="-1">Cancelling and refunds <a class="header-anchor" href="#cancelling-and-refunds" aria-label="Permalink to &quot;Cancelling and refunds&quot;">​</a></h2><ul><li>Clients can cancel only until the cutoff set by the platform (a number of hours before the start). Staff are not bound by it.</li><li>An <strong>online</strong> payment is refunded automatically. If the refund cannot be made, the cancellation does not go through.</li><li>A <strong>manual</strong> payment is marked as needing a manual refund.</li><li><strong>Cash</strong> or unpaid bookings have nothing to refund.</li><li>A cancelled booking from a package gives the session back.</li><li>On a client&#39;s package you can book a session for them, add sessions, set or remove the trainer (training packages) and extend the expiry date. Extending an expired package that still has sessions makes it active again.</li><li>You can <strong>cancel a client&#39;s package</strong> as long as no money is held for it (unpaid, cash, or already refunded). Its upcoming sessions are cancelled with it and the client is notified. A package that was paid for is cancelled by <strong>refunding its purchase</strong> instead, and a package that came with a membership cannot be cancelled on its own.</li><li>You can also extend a client&#39;s membership expiry date; an expired membership becomes active again. The packages that came with it keep their own dates.</li><li>Check a member in when they arrive; every check-in is added to the membership&#39;s log, which also lists the guests the member invited (with the visit created for each). Checking in does not change any booking, and only active memberships can be checked in.</li></ul><h2 id="unpaid-bookings" tabindex="-1">Unpaid bookings <a class="header-anchor" href="#unpaid-bookings" aria-label="Permalink to &quot;Unpaid bookings&quot;">​</a></h2><p>An online booking that is not paid within the hold time is cancelled automatically. If the payment arrives afterwards, it is refunded automatically.</p><h2 id="why-a-booking-is-refused" tabindex="-1">Why a booking is refused <a class="header-anchor" href="#why-a-booking-is-refused" aria-label="Permalink to &quot;Why a booking is refused&quot;">​</a></h2><p>Common reasons: the slot is full or in the past, the service is inactive, the client is blocked by your center, a block or closure overlaps, or the service type&#39;s booking option is switched off.</p>',18)])])}const p=t(s,[["render",i]]);export{u as __pageData,p as default};
